import {createChatOrchestrator} from './chatOrchestrator.js';
import {ToolRegistry} from './tools/registry.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk, UsageMetadata} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

describe('turn usage', () => {
  // specs/hal-engine-config-hooks/spec.md#10
  it('sums usage across a tool call and its answer', async () => {
    let calls = 0;
    let reported: UsageMetadata | undefined;
    const provider: AIProvider = {
      async *sendMessage(): AsyncGenerator<MessageChunk> {
        if (calls++ === 0) {
          yield {type: 'tool_use', toolCall: {id: '1', name: 'lookup', input: {}}};
          yield {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 3, outputTokens: 2, totalTokens: 5}};
        } else {
          yield {type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 7, outputTokens: 4, totalTokens: 11}};
        }
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };
    const registry = new ToolRegistry();
    registry.register({name: 'lookup', description: 'Lookup', inputSchema: {type: 'object'}}, async () => 'found');
    const session: ChatSession = {
      sessionId: 'session', userId: 'user',
      entries: [{role: 'user', content: 'Look up', timestamp: '2026-01-01T00:00:00.000Z'}],
    };
    const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'Test'}), registry, {
      hooks: {afterModelResponse: async (_session, _text, usage) => { reported = usage; }},
    });

    await orchestrator.processMessage(session);

    expect(reported).toEqual({inputTokens: 10, outputTokens: 6, totalTokens: 16});
  });
});
EOF
 timeout 300 node --experimental-vm-modules node_modules/jest/bin/jest.js --runInBand --runTestsByPath src/orchestration/usageAggregation.test.ts"
